using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.Data;
using System.Text;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
using DevExpress.XtraEditors;

namespace Jamera.Items.Units
{
    public partial class Units : DevExpress.XtraEditors.XtraUserControl
    {
        //String Message_Title = "Error Alert";
        public Units()
        {
            InitializeComponent();
            // This line of code is generated by Data Source Configuration Wizard
            // Fill a SqlDataSource
            sqlDataSource1.Fill();
        }

        private void create_new_btn_Click(object sender, EventArgs e)
        {
            search_inp.Focus();
            New_Unit new_unit = new New_Unit();
            new_unit.units = this;
            new_unit.Do_Refresh = true;
            new_unit.ShowDialog(this);
        }

        public void Refresh_Grid_Data()
        {
            search_inp.Text = null;
            this.Enabled = false;
            sqlDataSource1.RebuildResultSchema();
            sqlDataSource1.Fill();
            list.Update();
            this.Enabled = true;
        }

        private void list_MouseDoubleClick(object sender, MouseEventArgs e)
        {
        }

        private void Units_List_Load(object sender, EventArgs e)
        {
            search_inp.Focus();
        }

        private void refresh_btn_Click(object sender, EventArgs e)
        {
            Refresh_Grid_Data();
            search_inp.Focus();
        }

        private void gridView1_DoubleClick(object sender, EventArgs e)
        {
            if (gridView1.DataRowCount > 0)
            {
                Unit unit = new Unit();
                unit.Id = Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns[0]));
                unit.Name = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns[1]));
                Edit_Unit edit_unit = new Edit_Unit(unit);
                edit_unit.units = this;
                edit_unit.Do_Refresh = true;
                edit_unit.ShowDialog(this);
            }
        }

        private void search_inp_EditValueChanged(object sender, EventArgs e)
        {
            gridView1.ApplyFindFilter(search_inp.Text);
        }

        public void Controls_List(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.F1 || e.KeyCode == Keys.Down)
            {
                gridView1.Focus();
            }
            if ((e.KeyCode == Keys.F2 || e.KeyCode == Keys.Enter) && list.ContainsFocus == true)
            {
                if (gridView1.DataRowCount > 0)
                {
                    Unit unit = new Unit();
                    unit.Id = Convert.ToInt32(gridView1.GetFocusedRowCellValue(gridView1.Columns[0]));
                    unit.Name = Convert.ToString(gridView1.GetFocusedRowCellValue(gridView1.Columns[1]));
                    Edit_Unit edit_unit = new Edit_Unit(unit);
                    edit_unit.units = this;
                    edit_unit.Do_Refresh = true;
                    edit_unit.ShowDialog(this);
                }
            }
            if (e.KeyCode == Keys.F3 || (e.Control && e.KeyCode == Keys.F))
            {
                search_inp.Focus();
            }
            if (e.KeyCode == Keys.F6 || (e.Control && e.KeyCode == Keys.N))
            {
                search_inp.Focus();
                New_Unit new_unit = new New_Unit();
                new_unit.units = this;
                new_unit.Do_Refresh = true;
                new_unit.ShowDialog(this);
            }
            if (e.KeyCode == Keys.F5 || (e.Control && e.KeyCode == Keys.R))
            {
                Refresh_Grid_Data();
                search_inp.Focus();
            }

        }

        private void search_inp_KeyDown(object sender, KeyEventArgs e)
        {
            Controls_List(sender, e);
        }

        private void list_KeyDown(object sender, KeyEventArgs e)
        {
            Controls_List(sender, e);
        }
    }
}
